    {
      "stepNumber": 1,
      "description": "Writing the prime factorisation of 20 and 30 in exponential form",
      "working": "Prime factorisation of 20 = 2 × 2 × 5 = 2² × 5\nPrime factorisation of 30 = 2 × 3 × 5 = 2¹ × 3¹ × 5¹",
      "marks": 1.0
    },
    {
      "stepNumber": 2,
      "description": "Calculating HCF from the prime factors",
      "working": "HCF(20, 30) = Product of the smallest power of each common prime factor\n= 2¹ × 5¹ = 10",
      "marks": 0.5
    },
    {
      "stepNumber": 3,
      "description": "Calculating LCM from the prime factors and stating final answers",
      "working": "LCM(20, 30) = Product of the greatest power of each prime factor involved\n= 2² × 3¹ × 5¹ = 4 × 3 × 5 = 60\n∴ HCF(20, 30) = 10 and LCM(20, 30) = 60",
      "marks": 0.5
    }
  ],
  "commonMistakes": [
    "Using the common division method (ladder method) instead of prime factorisation; CBSE awards zero or partial marks if the specified method is not used.",
    "Confusing powers: selecting the highest power for HCF and lowest power for LCM.",
    "Omitting the non-common factor (3) while calculating LCM."
  ],
  "examTip": "Always express the prime factorisations in index/exponential form (e.g., 2² × 5) before writing HCF and LCM. This prevents power confusion and guarantees full step-marks under the CBSE marking scheme."
}

